                                        { text: "There is no difference", correct: false },
                                        { text: "Vulnerability maintains boundaries; oversharing dumps problems without consideration", correct: true },
                                        { text: "Oversharing is just more vulnerability", correct: false },
                                        { text: "Vulnerability is only for therapy", correct: false }
